    const bx = new T.BoxGeometry( 1, 1, 1 ), cyl = new T.CylinderGeometry( 1, 1, 1, 24, 1 ), cone = new T.ConeGeometry( 1, 1, 24, 1 );
    const ban = new T.PlaneGeometry( 1, 1, 1, 8 ), gable = new T.BufferGeometry();
